  assert.deepEqual(validateCustomer({ id: 'C-100', name: 'X', email: 'nope' }), { ok: false, error: 'CUSTOMER_INVALID' });
});

test('mergeCustomers rejects unknown fromId', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-999', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers rejects unknown intoId', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-999');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers rejects same customer', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers removes fromId customer', () => {
  const customers = listCustomers();
  const originalCount = customers.length;
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, originalCount - 1);
  assert(!result.value.customers.find((c) => c.id === 'C-001'));
  assert(result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers preserves intoId customer', () => {
  const customers = listCustomers();
  const intoCustomer = customers.find((c) => c.id === 'C-002');
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const mergedCustomer = result.value.customers.find((c) => c.id === 'C-002');
  assert.deepEqual(mergedCustomer, intoCustomer);
});

test('mergeCustomers updates invoices from fromId to intoId', () => {
  const customers = listCustomers();

  // Create invoices for both customers
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });

  assert.equal(r1.ok, true);
  assert.equal(r2.ok, true);

  const invoices = [
    issueInvoice(r1.value, []).value,
    issueInvoice(r2.value, ['INV-2024-0001']).value,
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  // First invoice should now belong to C-002
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  // Second invoice should still belong to C-002
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers with no invoices', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('mergeCustomers does not mutate input customers', () => {
  const customers = listCustomers();
  const originalCustomers = JSON.parse(JSON.stringify(customers));

  mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.deepEqual(customers, originalCustomers);
});

test('mergeCustomers does not mutate input invoices', () => {
  const customers = listCustomers();

  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r1.ok, true);
  const invoices = [issueInvoice(r1.value, []).value];
  const originalInvoices = JSON.parse(JSON.stringify(invoices));

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.deepEqual(invoices, originalInvoices);
});

test('mergeCustomers normalizes customer IDs', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'c-001', 'C-002');

  assert.equal(result.ok, true);
  assert(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers with mixed case and whitespace', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], ' c-001 ', ' C-002 ');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
});

test('mergeCustomers keeps all other customers', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.equal(result.ok, true);
  // Should have all original customers minus the merged one
  const originalIds = new Set(customers.map((c) => c.id));
  const resultIds = new Set(result.value.customers.map((c) => c.id));

  originalIds.delete('C-001');
